SELECT t.task_id, t.user_id, t.file_key, t.status, t.sync_status, t.sync_error, t.prompt_country, t.raw_data, t.confirmed_data, t.image_urls, t.anomaly_summary, t.ai_raw_output, t.processed_by, t.created_at, t.updated_at FROM tasks t LEFT JOIN users u ON t.user_id = u.id WHERE 1=1
AND t.user_id = #{userId}
AND t.status = #{status}
AND t.task_id LIKE CONCAT('%', #{keyword}, '%')
AND t.file_key LIKE CONCAT('%', #{keyword}, '%')
AND (u.real_name LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%'))
AND t.status = #{keyword}
AND DATE_FORMAT(t.created_at, '%Y-%m-%d %H:%i:%s') LIKE CONCAT('%', #{keyword}, '%')
AND (t.task_id LIKE CONCAT('%', #{keyword}, '%') OR t.file_key LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY t.created_at DESC LIMIT #{offset}, #{size}

